WITH exploded AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, v) SELECT CASE WHEN status_code >= 429 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, MAX(log_ts) AS last_log_ts, MAX(status_code) FILTER (WHERE host = 'h1') AS h1_max_status_code, BIT_OR(latency_ms) AS latency_ms_bit_or FROM exploded GROUP BY CASE WHEN status_code >= 429 THEN 'HIGH' ELSE 'LOW' END HAVING BIT_OR(latency_ms) > 1 ORDER BY latency_ms_bit_or NULLS FIRST;
